from sage.all_cmdline import *   # import sage library

_sage_const_300 = Integer(300); _sage_const_250 = Integer(250); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_10 = Integer(10); _sage_const_8 = Integer(8); _sage_const_1000 = Integer(1000); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_100 = Integer(100); _sage_const_6 = Integer(6); _sage_const_7 = Integer(7); _sage_const_5 = Integer(5); _sage_const_1p0 = RealNumber('1.0')# ---------------------------------------------------------
# <cos_arctan_sin_arctan>
#   cos(arctan x) = 1 / sqrt(1+x^2)^{(R_{>=0})}
#   sin(arctan x) = x / sqrt(1+x^2)^{(R_{>=0})}
#
# 独立経路:
#   左辺は arctan の値を求めてから cos / sin を評価する（角度を経由する経路）。
#   右辺は x から代数的に組み上げる（角度を経由しない経路）。平方根は組み込みを使わず
#   <sqrt_nonnegative_existence_uniqueness> の存在証明と同じ二分法で構成する。
#
# 本文の arctan / sin / cos は円弧の長さと arcsin の逆関数として定義域を
# [-pi/2, pi/2] に制限して定義されている（<calc_formulae_014...>）。Sage の
# arctan / sin / cos はその範囲で本文の定義と一致するので、左辺の評価に用いる。
# 一致していること自体も check_02 で確認する。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

RF = RealField(_sage_const_300 )
ITERS = _sage_const_250 

def sqrt_nonneg_bisect(a):
    a = RF(a)
    lo, hi = RF(_sage_const_0 ), RF(_sage_const_1 ) + a
    for _ in range(ITERS):
        mid = (lo + hi) / _sage_const_2 
        if mid * mid <= a:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / _sage_const_2 

XS = [RF(v) for v in [
    _sage_const_0 , _sage_const_1 /_sage_const_10 **_sage_const_8 , -_sage_const_1 /_sage_const_10 **_sage_const_8 , _sage_const_1 /_sage_const_1000 , -_sage_const_1 /_sage_const_1000 , _sage_const_1 /_sage_const_3 , -_sage_const_1 /_sage_const_3 , _sage_const_1 /_sage_const_2 , -_sage_const_1 /_sage_const_2 ,
    _sage_const_1 , -_sage_const_1 , _sage_const_2 , -_sage_const_2 , _sage_const_3 , -_sage_const_3 , _sage_const_4 /_sage_const_3 , -_sage_const_4 /_sage_const_3 , _sage_const_10 , -_sage_const_10 , _sage_const_100 , -_sage_const_100 , _sage_const_10 **_sage_const_6 , -_sage_const_10 **_sage_const_6 ,
    # phi_polar で実際に現れる y/x（テスト点由来）
    _sage_const_4 /_sage_const_3 , -_sage_const_4 /_sage_const_3 , _sage_const_3 /_sage_const_7 *(-_sage_const_5 /_sage_const_4 ), _sage_const_1 /_sage_const_100 , -_sage_const_1 /_sage_const_100 ,
]]

rep = CheckReport("<cos_arctan_sin_arctan> cos/sin(arctan x) の閉じた表示")

for x in XS:
    t = RF(x).arctan()
    lhs_c, lhs_s = t.cos(), t.sin()
    d = sqrt_nonneg_bisect(_sage_const_1  + x**_sage_const_2 )
    rhs_c, rhs_s = _sage_const_1  / d, x / d
    rep.close(float(lhs_c), float(rhs_c), "cos(arctan x) @x=%s" % x)
    rep.close(float(lhs_s), float(rhs_s), "sin(arctan x) @x=%s" % x)
    # 値域: arctan の値は [-pi/2, pi/2]
    rep.truth(-RF(pi) / _sage_const_2  <= t <= RF(pi) / _sage_const_2 , "arctan x in [-pi/2,pi/2] @x=%s" % x)
    # Pythagoras: 閉じた表示が単位円上にあること
    rep.close(float(rhs_c**_sage_const_2  + rhs_s**_sage_const_2 ), _sage_const_1p0 , "cos^2+sin^2=1（閉じた表示）@x=%s" % x)

rep.finish()

